/* Token Launch Radar: dark radar theme. One signal green, one amber warning, 8-point rhythm. */
:root {
  --bg: #0b0f14;
  --bg-deep: #080b10;
  --panel: #101720;
  --panel-2: #141d28;
  --panel-3: #18222f;
  --line: #1f2b3a;
  --line-soft: #18222e;
  --text: #e9eff7;
  --text-2: #c3cfdd;
  --muted: #9aabc0;
  --dim: #8496a9;
  --green: #3ce08c;
  --green-soft: #1d5c42;
  --green-wash: rgba(60, 224, 140, 0.10);
  --amber: #f2a93b;
  --amber-wash: rgba(242, 169, 59, 0.12);
  --s1: 4px; --s2: 8px; --s3: 16px; --s4: 24px; --s5: 32px; --s6: 48px; --s7: 64px;
  --radius: 8px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
}
*, *::before, *::after { box-sizing: border-box; }
html { background: var(--bg); }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.45;
  color: var(--text);
  background:
    radial-gradient(1100px 520px at 12% -8%, rgba(60, 224, 140, 0.06), transparent 70%),
    radial-gradient(900px 480px at 96% 0%, rgba(242, 169, 59, 0.045), transparent 68%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3 { margin: 0; font-weight: 650; letter-spacing: -0.01em; line-height: 1.2; }
p { margin: 0 0 var(--s3); }
p:last-child { margin-bottom: 0; }
a { color: var(--green); }
.visually-hidden, .skip:not(:focus) {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.skip { position: absolute; left: var(--s3); top: var(--s2); z-index: 40; padding: 6px var(--s3);
  background: var(--green); color: #05210f; border-radius: 6px; font-weight: 650; }
:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }

/* Brand bar: one line, sticky, with the snapshot and model chips */
.topbar {
  position: sticky; top: 0; z-index: 20;
  background: rgba(11, 15, 20, 0.9);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line-soft);
}
.bar-in {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s3);
  height: 36px; max-width: 1560px; margin: 0 auto; padding: 0 var(--s4);
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-name { font-size: 13px; font-weight: 650; letter-spacing: 0.02em; }
.scope {
  position: relative; width: 18px; height: 18px; border-radius: 50%; flex: none;
  border: 1px solid var(--green-soft);
  background:
    repeating-radial-gradient(circle at center, transparent 0 3.4px, rgba(60, 224, 140, 0.16) 3.4px 3.9px),
    radial-gradient(circle at center, rgba(60, 224, 140, 0.22), rgba(60, 224, 140, 0.02) 70%);
}
.scope::before {
  content: ""; position: absolute; inset: 0; border-radius: 50%;
  background: conic-gradient(from 0deg, rgba(60, 224, 140, 0.55), rgba(60, 224, 140, 0) 38%, transparent 100%);
  animation: sweep 5s linear infinite;
}
.scope::after {
  content: ""; position: absolute; left: 11px; top: 4px; width: 4px; height: 4px; border-radius: 50%;
  background: var(--green); box-shadow: 0 0 7px rgba(60, 224, 140, 0.9);
}
@keyframes sweep { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
  .scope::before { animation: none; }
}
.topmeta { display: flex; align-items: center; gap: 6px; min-width: 0; }
.chip {
  font-family: var(--mono); font-size: 10.5px; letter-spacing: 0.05em; text-transform: uppercase;
  padding: 2px 8px; border-radius: 999px; font-variant-numeric: tabular-nums;
  color: var(--green); border: 1px solid var(--green-soft); background: var(--green-wash);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.chip-quiet { color: var(--muted); border-color: var(--line); background: transparent; }

/* Layout */
main { display: block; padding: 0 var(--s4) var(--s6); max-width: 1560px; margin: 0 auto; }

/* Hero: a heading, one line of method, one strip of four counts */
.hero { padding: var(--s3) 0 0; }
.hero h1 { font-size: clamp(19px, 1.75vw, 23px); max-width: 62ch; margin-bottom: 6px; }
.lede { color: var(--text-2); font-size: 12.5px; line-height: 1.5; max-width: 132ch; margin: 0; }
.stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px;
  margin: var(--s2) 0 0; padding: 0; background: var(--line-soft);
  border: 1px solid var(--line-soft); border-radius: var(--radius); overflow: hidden;
}
.stat { background: var(--panel); padding: 5px var(--s3) 6px; min-width: 0; }
.stat dt { font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }
.stat dd {
  margin: 0; font-family: var(--mono); font-size: 15px; font-weight: 600; line-height: 1.35;
  color: var(--text); font-variant-numeric: tabular-nums; white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis;
}
.stat dd small {
  font-family: var(--font); font-size: 10.5px; font-weight: 400; color: var(--dim);
  margin-left: 6px; letter-spacing: 0; text-transform: none;
}
@media (max-width: 900px) {
  .stat dd { white-space: normal; }
  .stat dd small { display: block; margin-left: 0; }
}
.stat-accent dd { color: var(--green); }
.stat-warn dd { color: var(--amber); }

/* Controls: one slim row */
.controls {
  display: grid; grid-template-columns: minmax(180px, 1.6fr) repeat(3, minmax(104px, 0.7fr)) minmax(280px, 1.4fr) auto;
  gap: 10px; align-items: end;
  margin: var(--s2) 0 var(--s3); padding: 7px 10px;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
}
.control { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.control label {
  font-size: 9.5px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--muted);
}
input[type="search"], select {
  width: 100%; padding: 3px 10px; min-height: 28px;
  color: var(--text); background: var(--bg-deep);
  border: 1px solid var(--line); border-radius: 6px;
  font: inherit; font-size: 13px;
}
input[type="search"]::placeholder { color: var(--dim); }
select { appearance: none; padding-right: 26px; cursor: pointer; }
.control select {
  background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%);
  background-position: calc(100% - 15px) 13px, calc(100% - 10px) 13px;
  background-size: 5px 5px, 5px 5px; background-repeat: no-repeat;
}
.toggle-row { display: flex; gap: 6px; flex-wrap: wrap; }
.toggle {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 10px; min-height: 28px; cursor: pointer; white-space: nowrap;
  font: inherit; font-size: 12px; color: var(--text-2);
  background: var(--bg-deep); border: 1px solid var(--line); border-radius: 999px;
  transition: color 120ms ease, border-color 120ms ease, background-color 120ms ease;
}
.toggle .dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--dim); flex: none;
  transition: background-color 120ms ease, box-shadow 120ms ease;
}
.toggle:hover { border-color: var(--green-soft); color: var(--text); }
.toggle[aria-pressed="true"] { color: var(--green); border-color: var(--green-soft); background: var(--green-wash); }
.toggle[aria-pressed="true"] .dot { background: var(--green); box-shadow: 0 0 6px rgba(60, 224, 140, 0.8); }
.control-reset { align-items: flex-end; }
.ghost {
  padding: 3px 12px; min-height: 28px; cursor: pointer;
  font: inherit; font-size: 12px; color: var(--muted);
  background: transparent; border: 1px solid var(--line); border-radius: 6px;
}
.ghost:hover { color: var(--text); border-color: var(--muted); }

/* Section heads: title, note and count on one line */
.section-head { display: flex; align-items: baseline; gap: var(--s3); margin-bottom: 6px; }
.section-head h2, .how h2 { font-size: 14px; letter-spacing: 0.02em; flex: none; }
.section-note { color: var(--muted); font-size: 11.5px; line-height: 1.4; margin: 0; flex: 1; min-width: 0; }
.count { font-family: var(--mono); font-size: 11px; color: var(--muted); white-space: nowrap; margin: 0; font-variant-numeric: tabular-nums; flex: none; }

/* Tables */
.table-scroll { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); }
table { width: 100%; border-collapse: collapse; }
caption { text-align: left; }
th, td { text-align: left; }
thead th {
  position: sticky; top: 0; z-index: 5;
  padding: 4px var(--s3);
  background: var(--panel-2);
  border-bottom: 1px solid var(--line);
  font-size: 9.5px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--muted); font-weight: 600;
  white-space: nowrap;
}
thead th .sort {
  all: unset; cursor: pointer; display: inline-flex; align-items: center; gap: 2px;
  font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit;
  padding: 0; min-height: 0;
}
thead th .sort:hover { color: var(--text); }
thead th[aria-sort="descending"] .sort, thead th[aria-sort="ascending"] .sort { color: var(--green); }
thead th[aria-sort] .sort::after {
  content: ""; width: 0; height: 0; margin-left: 3px; flex: none;
  border-left: 3px solid transparent; border-right: 3px solid transparent;
}
thead th[aria-sort="descending"] .sort::after { border-top: 4px solid var(--green); }
thead th[aria-sort="ascending"] .sort::after { border-bottom: 4px solid var(--green); }
th.num, td.num { text-align: right; font-variant-numeric: tabular-nums; }
.board-table td { padding: 4px var(--s3); border-bottom: 1px solid var(--line-soft); vertical-align: middle; }
.board-table tbody tr { cursor: pointer; transition: background-color 100ms ease; }
.board-table tbody tr:hover { background: var(--panel-2); }
.board-table tbody tr.is-open { background: var(--green-wash); box-shadow: inset 2px 0 0 var(--green); }
.board-table tbody tr.is-unlikely td { color: var(--dim); }
.board-table tbody tr.is-unlikely .name { color: var(--text-2); }
.board-table tbody tr:last-child td { border-bottom: 0; }
.num, .mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.cell-rank { color: var(--dim); font-size: 12px; width: 46px; }
.name { font-weight: 600; color: var(--text); display: block; }
td.cell-name .name {
  appearance: none; -webkit-appearance: none;
  margin: 0; padding: 0; border: 0; background: none;
  font: inherit; font-weight: 600; font-size: 13.5px; line-height: 1.3;
  color: var(--text); text-align: left; cursor: pointer;
}
.name:hover { color: var(--green); }
.slug { display: block; font-family: var(--mono); font-size: 10px; line-height: 1.3; color: var(--dim); }
.cat { font-size: 12px; color: var(--text-2); white-space: nowrap; }
.chains { font-size: 11.5px; color: var(--muted); white-space: nowrap; }
.cell-value { font-size: 14px; font-weight: 600; color: var(--green); }
.cell-band { display: block; font-size: 10px; line-height: 1.25; color: var(--dim); white-space: nowrap; }
.cell-airdrop { color: var(--text-2); font-size: 13px; }
.board-table td.num { font-size: 13px; }
.pos { color: var(--green); }
.neg { color: var(--amber); }
.badge {
  display: inline-block; font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.05em; text-transform: uppercase;
  padding: 1px 6px; border-radius: 3px; white-space: nowrap;
  color: var(--green); border: 1px solid var(--green-soft); background: var(--green-wash);
}
.badge-warn { color: var(--amber); border-color: rgba(242, 169, 59, 0.4); background: var(--amber-wash); }
td.cell-name .meta-row { display: flex; align-items: center; gap: 6px; min-width: 0; }
.tag { display: block; font-family: var(--mono); font-size: 9.5px; line-height: 1.3; color: var(--amber); max-width: 190px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.empty { margin: var(--s3) 0 0; padding: var(--s4); color: var(--muted); text-align: center; border: 1px dashed var(--line); border-radius: var(--radius); }

/* Reference table */
.reference { margin-top: var(--s5); }
.ref-table th, .ref-table td { padding: 4px var(--s3); border-bottom: 1px solid var(--line-soft); font-size: 12px; }
.ref-table tbody tr:last-child td { border-bottom: 0; }
.ref-table td { color: var(--text-2); }
.ref-table .name { font-weight: 500; }

/* How it works */
.how { margin-top: var(--s5); }
.how-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: var(--s3); margin-top: var(--s2); }
.how-card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: var(--s3) var(--s3) 10px; }
.how-card h3 { display: flex; align-items: center; gap: 8px; font-size: 13.5px; margin-bottom: 10px; }
.how-card .step {
  display: inline-grid; place-items: center; width: 19px; height: 19px; border-radius: 50%; flex: none;
  font-family: var(--mono); font-size: 10px; color: var(--green);
  border: 1px solid var(--green-soft); background: var(--green-wash);
}
.how-card p { color: var(--text-2); font-size: 12px; line-height: 1.5; margin-bottom: 10px; }
.formula, .assumption {
  font-family: var(--mono); font-size: 10.5px; line-height: 1.65; color: var(--text);
  background: var(--bg-deep); border: 1px solid var(--line-soft); border-left: 2px solid var(--green);
  border-radius: 6px; padding: 8px 10px; overflow-x: auto; margin: 0 0 10px;
}
.assumption { border-left-color: var(--amber); color: var(--text-2); }

/* Footer */
.foot { border-top: 1px solid var(--line-soft); padding: var(--s4) var(--s4) var(--s5); color: var(--dim); font-size: 11.5px; }
.foot-in { max-width: 1560px; margin: 0 auto; }
.foot strong { color: var(--muted); font-weight: 600; }
.foot p { max-width: 104ch; }
.foot-facts { font-family: var(--mono); font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; margin-bottom: 6px; }

/* Detail drawer */
.detail {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 30;
  width: min(540px, 100vw);
  background: var(--panel); border-left: 1px solid var(--line);
  box-shadow: -32px 0 64px rgba(0, 0, 0, 0.45);
  transform: translateX(100%); transition: transform 180ms ease;
  overflow: hidden;
}
.detail[hidden] { display: none; }
.detail.is-open { transform: translateX(0); }
.detail-inner { display: flex; flex-direction: column; height: 100%; }
.detail-head {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s3);
  padding: var(--s3); border-bottom: 1px solid var(--line); background: var(--panel-2);
}
.detail-kicker { font-family: var(--mono); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--green); margin: 0 0 2px; }
.detail-head h2 { font-size: 19px; }
.detail-sub { margin: 2px 0 0; font-size: 11.5px; color: var(--muted); }
.close {
  flex: none; padding: 4px 10px; cursor: pointer;
  font: inherit; font-size: 11.5px; color: var(--text-2);
  background: var(--bg-deep); border: 1px solid var(--line); border-radius: 6px;
}
.close:hover { color: var(--text); border-color: var(--muted); }
.detail-body { padding: var(--s3) var(--s3) var(--s4); overflow-y: auto; flex: 1; }
.detail h3 { font-size: 10px; letter-spacing: 0.11em; text-transform: uppercase; color: var(--muted); margin: var(--s4) 0 8px; }
.detail h3:first-child { margin-top: 0; }
.detail .value-hero { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.detail .value-hero b { font-family: var(--mono); font-size: 28px; font-weight: 600; color: var(--green); font-variant-numeric: tabular-nums; letter-spacing: -0.02em; }
.detail .value-hero span { font-size: 11.5px; color: var(--muted); }
.breakdown { display: grid; grid-template-columns: 1fr auto; gap: 5px var(--s3); margin: 0; font-size: 12px; }
.breakdown dt { color: var(--muted); }
.breakdown dd { margin: 0; font-family: var(--mono); font-variant-numeric: tabular-nums; color: var(--text); text-align: right; }
.breakdown .total dt { color: var(--text); font-weight: 600; padding-top: 6px; border-top: 1px solid var(--line); }
.breakdown .total dd { color: var(--green); font-weight: 600; padding-top: 6px; border-top: 1px solid var(--line); font-size: 14px; }
.breakdown .adj { color: var(--text-2); }
.note {
  margin-top: 10px; padding: 8px 10px; font-size: 11.5px; line-height: 1.5; color: var(--text-2);
  background: var(--bg-deep); border: 1px solid var(--line-soft); border-left: 2px solid var(--amber); border-radius: 6px;
}
.note strong { color: var(--amber); }
.standing { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--text-2); }
.bar { position: relative; flex: 1; height: 5px; border-radius: 3px; background: var(--panel-3); overflow: hidden; }
.bar i { position: absolute; inset: 0 auto 0 0; background: linear-gradient(90deg, var(--green-soft), var(--green)); border-radius: 3px; }
.plan { list-style: none; counter-reset: plan; margin: 0; padding: 0; display: grid; gap: 6px; }
.plan li {
  counter-increment: plan; display: grid; grid-template-columns: 22px 1fr; gap: 10px;
  padding: 8px 10px; background: var(--bg-deep); border: 1px solid var(--line-soft); border-radius: 6px;
}
.plan li::before {
  content: counter(plan); font-family: var(--mono); font-size: 10px; color: var(--green);
  display: grid; place-items: center; width: 19px; height: 19px; border-radius: 50%;
  border: 1px solid var(--green-soft); background: var(--green-wash);
}
.plan p { font-size: 12px; line-height: 1.5; color: var(--text-2); margin: 0 0 6px; }
.plan .meta { display: flex; gap: 6px; flex-wrap: wrap; }
.plan .meta span {
  font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.04em; text-transform: uppercase;
  padding: 1px 6px; border-radius: 3px; color: var(--muted);
  border: 1px solid var(--line); background: var(--panel);
}
.plan .meta .cost { color: var(--amber); border-color: rgba(242, 169, 59, 0.3); }
.plan .meta .time { color: var(--green); border-color: var(--green-soft); }

@media (max-width: 1180px) {
  .controls { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .control-search, .control-toggles { grid-column: span 2; }
}
@media (max-width: 900px) {
  .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .section-head { flex-wrap: wrap; }
  .section-note { order: 3; flex-basis: 100%; }
}
@media (max-width: 720px) {
  main { padding: 0 var(--s3) var(--s5); }
  .bar-in { padding: 0 var(--s3); }
  .controls { grid-template-columns: 1fr 1fr; }
  .control-search, .control-toggles, .control-reset { grid-column: 1 / -1; }
  .hero h1 { font-size: 18px; }
  .board-table td, .board-table thead th { padding: 4px var(--s2); }
  .detail { width: 100vw; }
}
